## 最小客户端示例

```javascript
const ws = new WebSocket("ws://127.0.0.1:32172/cli/v1/ws");

ws.onopen = () => {
  ws.send(JSON.stringify({
    type: "hello",
    client_id: "web",
    token: "your-token",
  }));
};

ws.onmessage = (e) => {
  const msg = JSON.parse(e.data);
  switch (msg.type) {
    case "hello_ok":
      // 鉴权成功，发送一条消息
      ws.send(JSON.stringify({ type: "input", text: "你好" }));
      break;
    case "chat":
    case "stream_append":
      console.log(msg.text);
      break;
    case "stream_replace":
      console.log("\n[最终] " + msg.text);
      break;
    case "stream_finish":
      console.log("\n--- 完成 ---");
      break;
    case "error":
      console.error("error: " + msg.text);
      break;
  }
};
```

更多前端示例见 [elbot-showcase/frontend](https://github.com/Elfreese/elbot-showcase/tree/main/frontend)。

